SakuraMiya said:
Okay, seems the image stays there even after I close and open the game as long as I keep the switch as a parallel process. Was that supposed to happen?
Click to expand...
The background image should only show so long as the switch is on, if the switch is off the background image will not show.
The fact you added this in a parrellel process means it simply pushes the switch on, which in terms shows the image.
This probably happens because the background is not saved during the save process, meaning you need to trigger the script again after loading, which you did through a parrallel event.
Try this script instead :
JavaScript:
(function () {
    var backgroundSwitch = 0;
    var backgroundImage = '';

    var _Scene_MenuBase_createBackground = Scene_MenuBase.prototype.createBackground;
    Scene_MenuBase.prototype.createBackground = function() {
        _Scene_MenuBase_createBackground.call(this);
        this._backgroundSprite = new Sprite();
        this.addChild(this._backgroundSprite);
        this.updateBackground();
    };

    Scene_MenuBase.prototype.updateBackground = function() {
        if ($gameSwitches.value(backgroundSwitch)) {
            this._backgroundSprite.bitmap = ImageManager.loadPicture(backgroundImage);
        } else {
            this._backgroundSprite.bitmap = null;
        }
    };

    var _Scene_MenuBase_terminate = Scene_MenuBase.prototype.terminate;
    Scene_MenuBase.prototype.terminate = function() {
        _Scene_MenuBase_terminate.call(this);
        if (this._backgroundSprite) {
            this.removeChild(this._backgroundSprite);
            this._backgroundSprite.bitmap = null;
            this._backgroundSprite = null;
        }
    };

    var _Game_Interpreter_pluginCommand = Game_Interpreter.prototype.pluginCommand;
    Game_Interpreter.prototype.pluginCommand = function(command, args) {
        _Game_Interpreter_pluginCommand.call(this, command, args);
        if (command === 'SetMenuBackground') {
            backgroundSwitch = Number(args[0]);
            backgroundImage = String(args[1]);
            // Save the plugin data
            $gameSystem._menuBackgroundData = { switchId: backgroundSwitch, image: backgroundImage };
        }
    };

    // Load plugin data when the game is loaded
    var _DataManager_loadGame = DataManager.loadGame;
    DataManager.loadGame = function(savefileId) {
        var result = _DataManager_loadGame.call(this, savefileId);
        if (result && $gameSystem._menuBackgroundData) {
            backgroundSwitch = $gameSystem._menuBackgroundData.switchId;
            backgroundImage = $gameSystem._menuBackgroundData.image;
        }
        return result;
    };

    // Save plugin data when the game is saved
    var _DataManager_saveGame = DataManager.saveGame;
    DataManager.saveGame = function(savefileId) {
        if (!$gameSystem._menuBackgroundData) {
            $gameSystem._menuBackgroundData = { switchId: backgroundSwitch, image: backgroundImage };
        }
        return _DataManager_saveGame.call(this, savefileId);
    };
})();
This should do the job, even without the parrallel event (as you should avoid using those if applicable).

